import download from "downloadjs"
import {addAlert, gettext, shortFileTitle, staticUrl} from "fwtoolkit"
import {
    emitPdfFromWindow,
    type EmitAttachment,
    type EmitMetadata,
    type PdfOptions,
    type PrintOptions
} from "pages-to-pdf"

import type {BibDB, CSL, ExportDoc, FidusNode, ImageDB} from "../../types.js"
import {PrintExporter} from "../print/index.js"
import {getPrintEngine} from "../print/engines/registry.js"
import {createSlug} from "../tools/file.js"

export interface PdfExporterOptions {
    /**
     * The Fidus Writer application version. Used as the PDF Producer string
     * (e.g. "Fidus Writer 4.1.7").
     */
    version?: string
    /**
     * The display name of the current Fidus Writer user. Used as the PDF
     * Creator string when the document itself declares no authors.
     */
    userName?: string
    /**
     * A pre-built `.fidus` file (bytes) to embed as a PDF attachment so the
     * PDF is self-contained with its editable source.
     */
    fidusFile?: Uint8Array | ArrayBuffer
    /** Print-production options (crop marks, trim/bleed boxes, link borders,
        SVG rasterization). */
    printOptions?: PrintOptions
    /**
     * Request PDF/A-4 archival conformance. Embedded files (e.g. an attached
     * `.fidus` source or an embedded source HTML) require PDF/A-4f instead;
     * the exporter upgrades the setting automatically in that case.
     */
    pdfA?: boolean | "4" | "4f"
    /**
     * Request PDF/UA-2 accessibility conformance (tagged PDF with a
     * structure tree).
     */
    pdfUa?: boolean
    /**
     * Embed the source HTML in the PDF as an attachment. Either `true`
     * (stored as "document.html") or a custom filename. Implies PDF/A-4f
     * when `pdfA` is requested.
     */
    embedSourceHtml?: boolean | string
    /**
     * The pagination engine to use. Must have been made available through
     * `registerPrintEngine()` if it is not the default. Defaults to
     * "paged-with-floats".
     */
    printEngine?: string
    /**
     * Place display (centered) figures as CSS page floats (moved to the top
     * of the page). Injected as overridable default CSS. Default: true.
     */
    figurePageFloats?: boolean
    /**
     * Place tables as CSS page floats (moved to the top of the page).
     * Injected as overridable default CSS. Default: true.
     */
    tablePageFloats?: boolean
}

/**
 * Export the document directly to a PDF, client-side, without the browser
 * print dialog. Reuses the print pipeline's HTML generation (pagination by
 * the selected print engine) and then runs the pages-to-pdf DOM-to-PDF
 * emitter on the paginated iframe to produce a real vector PDF, which is
 * downloaded.
 */
export class PdfExporter extends PrintExporter {
    options: PdfExporterOptions

    constructor(
        doc: ExportDoc,
        bibDB: BibDB,
        imageDB: ImageDB,
        csl: CSL,
        updated: Date,
        documentStyles: Array<{
            slug: string
            contents: string
            documentstylefile_set: Array<[string, string]>
        }>,
        progressCallback?: (
            message: string,
            percentage?: number | null
        ) => void,
        options: PdfExporterOptions = {}
    ) {
        super(
            doc,
            bibDB,
            imageDB,
            csl,
            updated,
            documentStyles,
            progressCallback,
            {
                printEngine: options.printEngine,
                figurePageFloats: options.figurePageFloats,
                tablePageFloats: options.tablePageFloats
            }
        )
        this.options = options
    }

    protected async buildMetadata(
        metaData: {
            title: string
            authors: FidusNode[]
            keywords: string[]
        }
    ): Promise<EmitMetadata> {
        const authorString = metaData.authors
            .map((author: FidusNode) => {
                const authorAttrs = author.attrs || {}
                const firstname = authorAttrs.firstname
                const lastname = authorAttrs.lastname
                const institution = authorAttrs.institution
                if (firstname || lastname) {
                    const nameParts: string[] = []
                    if (typeof firstname === "string") {
                        nameParts.push(firstname)
                    }
                    if (typeof lastname === "string") {
                        nameParts.push(lastname)
                    }
                    return nameParts.join(" ")
                } else if (typeof institution === "string") {
                    return institution
                }
                return ""
            })
            .filter(Boolean)
            .join(", ")
        const metadata: EmitMetadata = {
            title: metaData.title,
            keywords: metaData.keywords.length
                ? metaData.keywords.join(", ")
                : undefined,
            language: this.doc.settings.language || "en-US",
            // Creator: the document's authors when present, otherwise the
            // current Fidus Writer user who initiated the export.
            creator: authorString.length
                ? authorString
                : this.options.userName,
            // Producer: the application that produced the PDF.
            producer: this.options.version
                ? `Fidus Writer ${this.options.version}`
                : "Fidus Writer"
        }
        if (authorString.length) {
            metadata.author = authorString
        }
        return metadata
    }

    async init(): Promise<void> {
        const title = shortFileTitle(this.doc.title, this.doc.path || "")
        this.progressCallback?.(
            `${title}: ${gettext("PDF export has been initiated.")}`,
            0
        )

        const {html, metaData} = await this.buildPaginatedHtml()

        this.progressCallback?.(
            `${title}: ${gettext("Rendering PDF…")}`,
            25
        )

        const metadata = await this.buildMetadata(metaData)
        // Name the download after the document title (not the folder path
        // segment that `docTitle`/`shortFileTitle` carries).
        const slug = createSlug(this.doc.title) || "document"
        const filename = `${slug}.pdf`

        const attachments: EmitAttachment[] = []
        if (this.options.fidusFile) {
            attachments.push({
                filename: `${slug}.fidus`,
                bytes: this.options.fidusFile,
                mimeType: "application/vnd.fiduswriter+zip",
                description:
                    "Fidus Writer source document (editable version of this PDF)"
            })
        }

        const fail = (message: string): void => {
            this.progressCallback?.(`${title}: ${message}`, 100)
            addAlert("error", message)
        }

        const engine = getPrintEngine(this.options.printEngine)

        const pdfOptions: PdfOptions = {}
        if (this.options.pdfUa) {
            pdfOptions.pdfUa = 2
        }
        if (this.options.pdfA) {
            // PDF/A-4 forbids embedded files — the conformance level is
            // upgraded to PDF/A-4f whenever files are attached.
            const embedsFiles =
                attachments.length > 0 || this.options.embedSourceHtml !== undefined
            pdfOptions.pdfA =
                embedsFiles && this.options.pdfA !== "4f"
                    ? "4f"
                    : this.options.pdfA
        }

        try {
            const paginated = await engine.preparePagination({
                html,
                title: metaData.title,
                polyfillURL: staticUrl("paged/paged.polyfill.js"),
                errorCallback: (errorMessage: string) => {
                    fail(`${gettext("PDF export failed.")} ${errorMessage}`)
                }
            })
            try {
                const bytes = await emitPdfFromWindow(paginated.win, {
                    onProgress: (message: string) =>
                        this.progressCallback?.(`${title}: ${message}`, null),
                    sourceHtml: html,
                    metadata,
                    printOptions: this.options.printOptions,
                    embedSourceHtml: this.options.embedSourceHtml,
                    // The fallback fonts, the WOFF2 decoder wasm and the
                    // PDF/A sRGB ICC profile are bundled in static-libs/
                    // and served from the app's static files. If they are
                    // missing, exports still work whenever the document's
                    // own fonts can be embedded, and the output intent is
                    // skipped.
                    baseUrl: staticUrl(""),
                    woff2WasmUrl: staticUrl("woff2/woff2.wasm"),
                    attachments,
                    pdfOptions,
                    backend: engine.backend
                })
                download(
                    new Blob([bytes as BlobPart], {
                        type: "application/pdf"
                    }),
                    filename,
                    "application/pdf"
                )
                this.progressCallback?.(
                    `${title}: ${gettext("PDF export complete.")}`,
                    100
                )
            } finally {
                paginated.cleanup()
            }
        } catch (error) {
            console.error(error)
            fail(gettext("PDF export failed."))
        }
    }
}
